const assert = require('node:assert/strict');
const { Ledger } = require('./.build/ledger');
const { PaymentService } = require('./.build/service');
const { Transient } = require('./.build/transport');

(async () => {
  // Default attempts=3 exhaustion: exactly 3 tries, same Transient instance rethrown.
  {
    const ledger = new Ledger();
    let tries = 0;
    const boom = new Transient('net');
    const service = new PaymentService(ledger, { acknowledge: async () => { tries++; throw boom; } });
    await assert.rejects(service.pay('t', 'k', 10), (e) => e === boom);
    assert.equal(tries, 3);
    assert.equal(ledger.entries.length, 1);
  }
  // attempts=undefined -> default; attempts as string -> invalid, no side effects.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    assert.deepEqual(await service.pay('t', 'k', 10, undefined), { id: 1, tenant: 't', key: 'k', cents: 10 });
    await assert.rejects(service.pay('t', 'k', 10, '3'), /invalid payment/);
    assert.equal(acks, 1);
  }
  // 50 concurrent same-key equal-amount pays with a flaky ack: one debit, all share the receipt.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, {
      acknowledge: async () => { if (Math.random() < 0.5) throw new Transient('x'); },
    });
    const all = await Promise.all(Array.from({ length: 50 }, () => service.pay('t', 'k', 42, 5)));
    assert.ok(all.every(r => r === all[0]));
    assert.equal(ledger.entries.length, 1);
    assert.equal(all[0].id, 1);
  }
  // Odd tenant/key strings, __proto__ keys, same key across tenants.
  {
    const ledger = new Ledger();
